import{_ as a,C as o,o as i,c as r,a2 as n,E as l}from"./chunks/framework.CtQGab4e.js";const m=JSON.parse('{"title":"Kozijnen koppelen","description":"","frontmatter":{},"headers":[],"relativePath":"plattegrond/kozijnen-koppelen.md","filePath":"plattegrond/kozijnen-koppelen.md"}'),d={name:"plattegrond/kozijnen-koppelen.md"};function s(p,e,k,g,z,h){const t=o("Media");return i(),r("div",null,[e[0]||(e[0]=n('<h1 id="kozijnen-koppelen" tabindex="-1">Kozijnen koppelen <a class="header-anchor" href="#kozijnen-koppelen" aria-label="Permalink to &quot;Kozijnen koppelen&quot;">​</a></h1><p>Na <strong>Genereer</strong> koppel je de <a href="./kozijnen.html">kozijnen</a> aan de constructies van het 3D-model. Alleen gekoppelde kozijnen gaan mee naar <a href="./label-wise.html">Label-wise</a>.</p><p>Open in het <a href="./3d-paneel.html">3D-paneel</a> het tabblad <strong>Kozijnen</strong>, naast <strong>Constructies</strong>. Het getal op het tabblad is het aantal kozijnen dat nog niet klaar is.</p>',3)),l(t,{todo:"Afbeelding: tabblad Kozijnen in het 3D-paneel, met een constructie die nog gekozen moet worden (⚠) en een geselecteerd kozijn."}),e[1]||(e[1]=n('<h2 id="vanzelf-gekoppeld" tabindex="-1">Vanzelf gekoppeld <a class="header-anchor" href="#vanzelf-gekoppeld" aria-label="Permalink to &quot;Vanzelf gekoppeld&quot;">​</a></h2><p>Heet de constructie van een kozijn precies zoals één constructie in het model, dan staat hij al goed. Je hoeft niets te doen.</p><p>Zelf kiezen moet als:</p><ul><li>de naam in meer zones voorkomt, bijvoorbeeld de achtergevel van een woning met twee zones: kies per kozijn de zone;</li><li>er geen constructie met die naam is.</li></ul><p>Een ⚠ staat bij alles wat nog gekozen moet worden.</p><h2 id="kiezen" tabindex="-1">Kiezen <a class="header-anchor" href="#kiezen" aria-label="Permalink to &quot;Kiezen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Hoe</th><th></th></tr></thead><tbody><tr><td><strong>Keuzelijst</strong></td><td>Naast elk kozijn. Bovenaan staan de constructies met dezelfde naam.</td></tr><tr><td><strong>In het model</strong></td><td>Tik een kozijn aan (<kbd>Ctrl</kbd> of <kbd>Shift</kbd> voor meer, of sleep met de muis over de kozijnen) en tik dan op een gevel of dak. Een tik op de naam van een constructie selecteert al zijn kozijnen.</td></tr><tr><td><strong>Niet meenemen</strong></td><td>Onderaan de keuzelijst, voor een kozijn dat niet in Label-wise hoort.</td></tr></tbody></table><p>Waar een kozijn aan hangt, zie je door met de muis over het kozijn te gaan. Het vierkantje voor een kozijn heeft de kleur van zijn zone; ✎ betekent: zelf gekozen.</p><h2 id="opnieuw-genereren" tabindex="-1">Opnieuw genereren <a class="header-anchor" href="#opnieuw-genereren" aria-label="Permalink to &quot;Opnieuw genereren&quot;">​</a></h2><p>Wat je gekozen hebt, blijft staan bij opnieuw genereren en als je een constructie hernoemt. Verandert de constructie zelf (een andere zone, begrenzing, isolatie of gebouwdeel, of een dakkapel gesplitst of samengevoegd), of heb je hem verwijderd, dan staat er <em>constructie bestaat niet meer</em>: koppel die kozijnen opnieuw.</p><p>Heb je zones toegevoegd, bijvoorbeeld koeling in een deel van het huis, dan kan een constructie nu in twee zones staan. Kozijnen die je daaraan gekoppeld had, krijgen <em>opnieuw kiezen</em>: kies per kozijn de zone, ook als het de oude is.</p><h2 id="klaar" tabindex="-1">Klaar? <a class="header-anchor" href="#klaar" aria-label="Permalink to &quot;Klaar?&quot;">​</a></h2><p>De export maakt geen Label-wise-bestand zolang er iets niet klopt. Dat gebeurt ook als:</p><ul><li>een kozijn geen m² heeft;</li><li>de kozijnen samen groter zijn dan hun constructie;</li><li>er geen enkel kozijn meegaat: een woning heeft altijd kozijnen, dus het koppelen is vergeten.</li></ul><p>Bij <strong>Exporteren</strong> staat dan wat er mis is, met de knop <strong>Naar Kozijnen</strong>.</p>',15))])}const c=a(d,[["render",s]]);export{m as __pageData,c as default};
